using System;using System.IO;using System.IO.Pipes;using System.Text;using System.Net;using System.Threading;using System.Threading.Tasks;
namespace IslandIntegrated {
 // Dormant until an explicitly authorized caller supplies its existing access
 // scope. No endpoint discovery, alternate host, credential lookup or elevation.
 public sealed class ExistingMihomoPipeTransport {
  readonly string name,selector;readonly bool readAuthorized,selectionAuthorized;bool denied;
  public ExistingMihomoPipeTransport(string configuredPath,string group,bool approvedRead,bool approvedSelection,bool priorAccessDenied){const string prefix=@"\\.\pipe\verge-mihomo-sidecar-release-";if(configuredPath==null||!configuredPath.StartsWith(prefix,StringComparison.Ordinal)||!System.Text.RegularExpressions.Regex.IsMatch(configuredPath.Substring(prefix.Length),"^[A-Za-z0-9-]{8,160}$"))throw new ArgumentException("Unexpected configured pipe");name=configuredPath.Substring(9);selector="/proxies/"+Uri.EscapeDataString(group);readAuthorized=approvedRead;selectionAuthorized=approvedSelection;denied=priorAccessDenied;}
  public Task<StatusServiceResponse> SendAsync(string method,string path,byte[] body,CancellationToken token){if(denied||!readAuthorized)return Task.FromResult(new StatusServiceResponse{Status=403});if(!(method=="GET"&&(path=="/version"||path==selector))&&!(selectionAuthorized&&method=="PUT"&&path==selector))return Task.FromResult(new StatusServiceResponse{Status=405});if(body!=null&&body.Length>4096)return Task.FromResult(new StatusServiceResponse{Status=413});return Task.Run(()=>{try{using(var client=new NamedPipeClientStream(".",name,PipeDirection.InOut,PipeOptions.Asynchronous))using(token.Register(()=>client.Dispose())){token.ThrowIfCancellationRequested();client.Connect(1200);var header=Encoding.ASCII.GetBytes(method+" "+path+" HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n"+(body==null?"":"Content-Type: application/json\r\nContent-Length: "+body.Length+"\r\n")+"\r\n");Write(client,header,token);if(body!=null)Write(client,body,token);using(var bytes=new MemoryStream()){var buffer=new byte[8192];while(true){var read=client.ReadAsync(buffer,0,buffer.Length,token);if(!read.Wait(1500,token))throw new TimeoutException();int n=read.Result;if(n==0)break;if(bytes.Length+n>557056)throw new InvalidDataException();bytes.Write(buffer,0,n);}return ParseHttp(bytes.ToArray());}}}catch(UnauthorizedAccessException){denied=true;return new StatusServiceResponse{Status=403};}catch(OperationCanceledException){throw;}catch{return new StatusServiceResponse{Status=503};}},token);}
  static void Write(Stream target,byte[] data,CancellationToken token){var task=target.WriteAsync(data,0,data.Length,token);if(!task.Wait(1500,token))throw new TimeoutException();task.GetAwaiter().GetResult();}
  public static StatusServiceResponse ParseHttp(byte[] bytes){if(bytes==null||bytes.Length>557056)throw new InvalidDataException();int split=-1;for(int i=0;i<bytes.Length-3&&i<32768;i++)if(bytes[i]==13&&bytes[i+1]==10&&bytes[i+2]==13&&bytes[i+3]==10){split=i;break;}if(split<0)throw new InvalidDataException();string headers=Encoding.ASCII.GetString(bytes,0,split);var match=System.Text.RegularExpressions.Regex.Match(headers,@"^HTTP/1\.[01] (\d{3})\b");if(!match.Success)throw new InvalidDataException();int status=Int32.Parse(match.Groups[1].Value);using(var output=new MemoryStream()){int position=split+4;if(System.Text.RegularExpressions.Regex.IsMatch(headers,@"(?im)^Transfer-Encoding:\s*chunked\s*$")){while(true){int end=position;while(end+1<bytes.Length&&!(bytes[end]==13&&bytes[end+1]==10))end++;if(end-position>32||end+1>=bytes.Length)throw new InvalidDataException();int length;if(!Int32.TryParse(Encoding.ASCII.GetString(bytes,position,end-position).Split(';')[0],System.Globalization.NumberStyles.HexNumber,System.Globalization.CultureInfo.InvariantCulture,out length)||length<0)throw new InvalidDataException();position=end+2;if(length==0)break;if(length>524288-output.Length||position+length+2>bytes.Length||bytes[position+length]!=13||bytes[position+length+1]!=10)throw new InvalidDataException();output.Write(bytes,position,length);position+=length+2;}}else{int length=bytes.Length-position;if(length>524288)throw new InvalidDataException();var declared=System.Text.RegularExpressions.Regex.Match(headers,@"(?im)^Content-Length:\s*(\d+)\s*$");if(declared.Success&&Int64.Parse(declared.Groups[1].Value)!=length)throw new InvalidDataException();output.Write(bytes,position,length);}return new StatusServiceResponse{Status=status,Body=new UTF8Encoding(false,true).GetString(output.ToArray())};}}
 }
 public sealed class DeepSeekBalanceHttpTransport {
  readonly Action<HttpWebRequest> approvedCredentialOwner;
  public DeepSeekBalanceHttpTransport(Action<HttpWebRequest> attachApprovedAuthentication){approvedCredentialOwner=attachApprovedAuthentication;}
  public async Task<StatusServiceResponse> SendAsync(Uri endpoint,CancellationToken token){if(approvedCredentialOwner==null)return new StatusServiceResponse{Status=401};if(endpoint==null||endpoint.AbsoluteUri!=DeepSeekBalanceAdapter.Endpoint.AbsoluteUri)throw new ArgumentException("Balance endpoint only");var request=(HttpWebRequest)WebRequest.Create(endpoint);request.Method="GET";request.AllowAutoRedirect=false;request.Timeout=12000;request.ReadWriteTimeout=12000;request.Accept="application/json";approvedCredentialOwner(request);if(String.IsNullOrWhiteSpace(request.Headers[HttpRequestHeader.Authorization]))return new StatusServiceResponse{Status=401};using(token.Register(()=>request.Abort())){HttpWebResponse response=null;try{response=(HttpWebResponse)await request.GetResponseAsync().ConfigureAwait(false);}catch(WebException e){token.ThrowIfCancellationRequested();response=e.Response as HttpWebResponse;if(response==null)return new StatusServiceResponse{Status=503};}using(response){int retry;int? after=Int32.TryParse(response.Headers["Retry-After"],out retry)&&retry>=0?(int?)retry:null;if((int)response.StatusCode!=200)return new StatusServiceResponse{Status=(int)response.StatusCode,RetryAfterSeconds=after};if(response.ContentLength>16384)return new StatusServiceResponse{Status=502};using(var body=response.GetResponseStream())using(var bytes=new MemoryStream()){var buffer=new byte[2048];int read;while((read=await body.ReadAsync(buffer,0,buffer.Length,token).ConfigureAwait(false))>0){if(bytes.Length+read>16384)return new StatusServiceResponse{Status=502};bytes.Write(buffer,0,read);}return new StatusServiceResponse{Status=200,Body=new UTF8Encoding(false,true).GetString(bytes.ToArray())};}}}}
 }
